function setFocus(enabled){focusView=Boolean(enabled);document.body.classList.toggle('chart-focus',focusView);const button=$('chartFocus');if(button){button.setAttribute('aria-pressed',String(focusView));button.textContent=focusView?'Exit chart focus':'Chart focus';button.title=focusView?'Return to the full dashboard':'Expand the chart and show a compact session rail';}requestAnimationFrame(()=>{if(typeof paint==='function')paint();});}
