async function api(path,body){const options={headers:{'Content-Type':'application/json'},signal:AbortSignal.timeout(50000)};if(body!==undefined){options.method='POST';options.body=JSON.stringify(body);}const response=await fetch('/api/jev-review/'+path,options);let json;try{json=await response.json();}catch{throw Error('Review service returned no readable receipt.');}if(!response.ok)throw Error(json.error||'Review service unavailable');return json;}
function fiveMode(){return (rows[0]?.paperSim?.strategy||$('paperStrategy').value)==='five-minute'&&$('paperEnabled').checked;}
function historyMinutes(){return fiveMode()?305:60;}
function aggregateFive(input){const groups=new Map();for(const b of input){const start=Math.floor(b.time/300000)*300000;if(!groups.has(start))groups.set(start,[]);groups.get(start).push(b);}return [...groups].filter(([start,g])=>g.length===5&&g.every((b,i)=>b.time===start+i*60000)).map(([time,g])=>({time,open:g[0].open,high:Math.max(...g.map(b=>b.high)),low:Math.min(...g.map(b=>b.low)),close:g.at(-1).close,volume:g.reduce((s,b)=>s+b.volume,0)}));}
