function pause(){if(phaseStart!=null){phaseMs=phase();phaseStart=null;}if(activeSince!=null){activeAccum+=performance.now()-activeSince;activeSince=null;}running=false;clearTimeout(timer);timer=null;controls();}
async function finish(){pause();setFocus(false);phaseMs=0;if(rows[0]?.paperSim){paperStatement=await api('finalize',{run:runId});message(`Paper session complete: ${paperStatement.summary.trades} trades · net ${money(paperStatement.summary.netPnl)}. Final P&L saved.`);}else message(`Session complete: ${completed} candles scored. Receipts remain saved.`);finished=true;render();}
function replayWindowKey(){return `jev-nextbar:last-window:${provider}:${symbol}`;}
function rememberReplayWindow(index){if(mode==='live'||!bars[index-1])return;try{const left=Math.max(0,index-historyMinutes()),right=Math.min(bars.length-1,index+durationMinutes-1);sessionStorage.setItem(replayWindowKey(),JSON.stringify({start:bars[left].time,end:bars[right].time,selected:bars[index].time}));}catch{}}
