function startOptions({randomize=false}={}){const select=$('replayStart'),current=Number(select.value),min=60,max=bars.length-durationMinutes;select.replaceChildren();for(let i=min;i<=max;i++){if(fiveMode()&&bars[i].time%300000!==0)continue;const option=document.createElement('option');option.value=i;option.textContent=`${dateTime(bars[i].time)} · ${bars.length-i} min available` ;select.append(option);}if(mode==='live'||max<min)return;const selected=!randomize&&current>=min&&current<=max&&(!fiveMode()||bars[current].time%300000===0)?current:randomReplayStart();select.value=String(selected);return selected;}
function reset(){pause();setFocus(false);history.replaceState(null,'',location.pathname);rows=[];pending=null;paperStatement=null;runId=crypto.randomUUID();completed=0;phaseMs=0;started=false;finished=false;archived=false;activeAccum=0;sessionGoal=durationMinutes;$('useJev').checked=jevConfigured!==false;if(mode==='live')cursor=bars.length;else{const selected=startOptions({randomize:true});if(selected!=null)cursor=selected;}sessionStartCursor=cursor;sessionBasePrice=bars[cursor-1]?.close??null;message(mode==='live'?'New forward session ready.':'New session ready with a randomized historical window. Previous server receipts remain saved.');render();}
function setSource(nextMode,newBars,newProvider,newSymbol){mode=nextMode;provider=newProvider;symbol=newSymbol;bars=validateBars(newBars);loaded=true;if(mode==='replay'&&provider==='hyperliquid'&&jevConfigured===true)$('paperEnabled').checked=true;reset();$('replayStartLabel').hidden=mode==='live';$('source').textContent=`${mode==='demo'?'DEMO DATA · SYNTHETIC':mode==='csv'?'USER CSV · '+symbol:'HYPERLIQUID · BTC'} · 1M${fiveMode()?' FILLS / 5M JEV + SAR':''} · ${mode==='live'?'FORWARD':mode==='demo'?'SEEDED REPLAY':'REAL DATA REPLAY'}`;}
async function resetRun(){if(archived&&mode==='replay'&&provider==='hyperliquid'){$('dataMode').value='replay';await load();return;}reset();}
async function load(){if(busy||running)return;busy=true;controls();try{const next=$('dataMode').value;if(next==='demo'){$('tick').value=.25;setSource(next,syntheticBars(crypto.getRandomValues(new Uint32Array(1))[0]),'synthetic','DEMO');}else if(next==='csv'){const file=$('csvFile').files[0];if(!file)throw Error('Choose a real one-minute CSV first.');if(file.size>5000000)throw Error('CSV must be smaller than 5 MB.');setSource(next,parseCSV(await file.text()),'csv',$('symbol').value.trim());}else{message('Loading real completed Hyperliquid BTC candles…');const data=await api(next==='live'?'source':'source?minutes=900');$('tick').value=1;setSource(next,data.bars,'hyperliquid','BTC');}message(next==='live'?'Forward chart ready. Session starts with the first fresh forecast.':'Real replay ready with a randomized historical window. Choose another start, session length and speed, then Start session.');}catch(e){message(e.message,true);}finally{busy=false;render();}}
function prepare(){settings();if(fiveMode()&&$('paperEntryPreset').value==='exploration'){const c=paperConfig();if(!Number.isFinite(c.stopBufferAtr)||c.stopBufferAtr<0||c.stopBufferAtr>3)throw Error('Stop buffer must be 0–3 times completed 1m ATR.');if(!Number.isFinite(c.costMargin)||c.costMargin<1||c.costMargin>5||!Number.isFinite(c.minNetRewardRisk)||c.minNetRewardRisk<.05||c.minNetRewardRisk>5)throw Error('Cost margin must be 1–5 and net reward/risk 0.05–5.');}if(fiveMode()&&(durationMinutes%5||bars[cursor]?.time%300000&& !started))throw Error('Choose a five-minute-aligned start and session length divisible by five.');if($('paperEnabled').checked){const c=paperConfig();if(mode!=='replay'||!$('useJev').checked)throw Error('The paper algo needs Hyperliquid BTC replay and Jev enabled.');if(!Number.isFinite(c.capital)||c.capital<100||c.capital>1000000||!['conservative','balanced','aggressive'].includes(c.riskProfile)||!Number.isFinite(c.maxRiskUsd)||c.maxRiskUsd<.01||c.maxRiskUsd>c.capital||!Number.isFinite(c.maxNotional)||c.maxNotional<10||c.maxNotional>c.capital||!Number.isFinite(c.feeBps)||c.feeBps<0||c.feeBps>100||!Number.isFinite(c.slippageBps)||c.slippageBps<0||c.slippageBps>100)throw Error('Check the paper balance, position cap, risk and cost assumptions.');}if($('useJev').checked&&durationMinutes>120)throw Error('Jev is limited to 120 forecasts (two hours) per session. Choose up to 120 minutes, or turn Jev off for a longer replay.');if(mode!=='live'&&bars.length-cursor<durationMinutes-completed)throw Error(`Only ${bars.length-cursor} replay minutes remain. Choose an earlier start or a shorter session.`);if(!started){started=true;sessionGoal=durationMinutes;sessionStartCursor=cursor;sessionBasePrice=bars[cursor-1]?.close??null;}}
