$('chart').onmousemove=e=>{hover=e.offsetX;paint();};$('chart').onmouseleave=()=>{hover=null;paint();};new ResizeObserver(paint).observe($('chart'));window.addEventListener('pagehide',pause);setInterval(sessionUI,200);
void api('status').then(x=>{$('connection').textContent=x.configured?`${x.model} · configured`:'Jev key missing';jevConfigured=Boolean(x.configured);if(!jevConfigured){$('useJev').checked=false;$('paperEnabled').checked=false;}controls();}).catch(e=>{$('connection').textContent='Review service unavailable';message(e.message,true);});
async function restore(savedRun){busy=true;controls();try{const saved=await api('run?run='+encodeURIComponent(savedRun));if(!saved.receipts.length)throw Error('No saved chart review found.');const first=saved.receipts[0],last=saved.receipts.at(-1);mode=first.source.kind;provider=first.source.provider;symbol=first.source.symbol;runId=savedRun;rows=saved.receipts;const known=new Map();for(const receipt of rows){for(const b of receipt.completedInput||[])known.set(b.time,b);if(receipt.actual)known.set(receipt.actual.time,receipt.actual);}bars=[...known.values()].sort((a,b)=>a.time-b.time);cursor=bars.length;loaded=true;pending=null;completed=rows.filter(r=>r.actual).length;durationMinutes=sessionGoal=Math.round((last.targetTime-first.targetTime)/60000)+1;sessionStartCursor=bars.findIndex(b=>b.time===first.targetTime);sessionBasePrice=first.completedInput.at(-1).close;started=true;archived=true;$('dataMode').value=mode;$('tick').value=first.tick;$('atrMult').value=first.atrMult;$('useJev').checked=first.jevEnabled;$('paperEnabled').checked=Boolean(first.paperSim);if(first.paperSim){$('paperStrategy').value=first.paperSim.strategy||'band-swing';$('paperEntryPreset').value=first.paperSim.entryPreset||'strict';$('paperCostMargin').value=first.paperSim.costMargin??1.25;$('paperRewardRisk').value=first.paperSim.minNetRewardRisk??.25;$('paperStopBuffer').value=first.paperSim.stopBufferAtr??0;paperStatement=await api('statement?run='+encodeURIComponent(runId));for(const [id,k] of Object.entries({paperCapital:'capital',paperNotional:'maxNotional',paperFee:'feeBps',paperSlip:'slippageBps',paperTakerFee:'takerFeeBps'}))$(id).value=first.paperSim[k]??(k==='takerFeeBps'?4.5:0);$('riskProfile').value=first.paperSim.riskProfile||'conservative';$('maxRiskUsd').value=first.paperSim.maxRiskUsd??(first.paperSim.capital*(first.paperSim.riskPct||.25)/100);durationMinutes=sessionGoal=first.paperSim.sessionMinutes;}$('source').textContent=`${provider.toUpperCase()} · ${symbol} · 1M${first.forecastMinutes===5?' FILLS / 5M JEV + SAR':''} · SAVED ${mode==='live'?'FORWARD':'REPLAY'} RECEIPTS`;history.replaceState(null,'',location.pathname+'?run='+encodeURIComponent(runId));message(`Restored ${fiveMode()?rows.filter(r=>!r.forecastReused).length:rows.length} frozen ${fiveMode()?'5m':'1m'} forecasts. Reset and Load chart for a new real replay.`);}catch(e){message(e.message,true);}finally{busy=false;render();}}
$('source').textContent='Loading chart…';render();if(initialSavedRun)void restore(initialSavedRun);else void load();
